{"path":"events.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Gatherings — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Upcoming community sound gatherings in {{CITY}}, {{STATE}}. Find the next public session and a compact calendar of upcoming dates.">
  <style>
    :root{--bg:#0f1720;--card:#071021;--muted:#9aa6b2;--accent:#88d1c9;--glass:rgba(255,255,255,0.04);--radius:12px}
    html,body{height:100%}
    body{margin:0;font-family:Inter,ui-sans-serif,system-ui,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#e6eef0;background:linear-gradient(180deg,#071021 0%, #071a27 60%),url("assets/img/pattern.svg");background-size:400px;line-height:1.45}
    header{display:flex;align-items:center;justify-content:space-between;padding:22px 28px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent)}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#5ea7ff);display:flex;align-items:center;justify-content:center;color:#022; font-weight:700}
    nav a{color:var(--muted);text-decoration:none;margin-left:18px;font-weight:600}
    nav a.active{color:var(--accent)}
    main{padding:28px;max-width:1100px;margin:20px auto}
    .hero{display:grid;grid-template-columns:1fr 350px;gap:24px;align-items:start}
    .panel{background:var(--card);border-radius:var(--radius);padding:20px;box-shadow:0 6px 20px rgba(2,6,23,0.6)}
    h1{color:#dff3f0;margin:0 0 8px;font-weight:700}
    .kicker{color:var(--accent);font-weight:700;letter-spacing:0.06em;font-size:13px}
    .next-event{background:linear-gradient(180deg,rgba(136,209,201,0.06),transparent);padding:16px;border-radius:10px;border:1px solid rgba(136,209,201,0.06)}
    .next-event time{display:block;font-weight:700;color:#e6f9f6}
    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin-top:14px}
    .card{background:var(--glass);padding:14px;border-radius:10px;border:1px solid rgba(255,255,255,0.03)}
    .muted{color:var(--muted);font-size:14px}
    .gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:12px}
    .tile{height:110px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));display:flex;align-items:center;justify-content:center;color:var(--muted);font-weight:600}
    .section{margin-top:20px}
    .cta{display:inline-block;padding:10px 16px;border-radius:10px;background:var(--accent);color:#022;font-weight:700;text-decoration:none}
    .calendar-list{list-style:none;padding:0;margin:0}
    .calendar-list li{padding:10px;border-radius:8px;margin-bottom:8px;background:rgba(255,255,255,0.01);display:flex;justify-content:space-between;align-items:center}
    .disclaimer{font-size:13px;color:#b6c6cb;margin-top:10px}
    /* reveal animation */
    .reveal{opacity:0;transform:translateY(18px);transition:opacity 520ms cubic-bezier(.2,.9,.2,1),transform 520ms cubic-bezier(.2,.9,.2,1)}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
    footer{color:var(--muted);text-align:center;padding:30px}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div>
        <div style="color:#dff3f0;font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="color:var(--muted);font-size:13px">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html" class="active">Gatherings</a>
      <a href="private-sessions.html">Solo Sessions</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">Story</a>
      <a href="faq.html">Answers</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>
  <main>
    <section class="hero reveal" id="hero">
      <div class="panel">
        <div class="kicker">COMMUNITY GATHERINGS</div>
        <h1>Public Sound Sessions — next convening</h1>
        <p class="muted">Join a compact, intentional public session in {{CITY}}, {{STATE}}. Each gathering has a guided arc: arrival, attunement, a layered sound field, and a gentle return.</p>
        <div class="section">
          <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>
      </div>
      <aside class="panel next-event">
        <div style="font-size:13px;color:var(--muted)">Next gathering</div>
        <time datetime="2026-03-05T18:30">Thu, Mar 5 · 6:30 PM</time>
        <div class="muted" style="margin-top:8px">Studio at {{CITY}}, {{STATE}} — limited capacity</div>
        <div style="margin-top:12px">
          <a href="book.html" class="cta">Reserve a seat</a>
        </div>
      </aside>
    </section>

    <section class="panel section reveal" id="calendar">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
        <div>
          <div style="font-weight:700;color:#e6f9f6">Upcoming dates</div>
          <div class="muted">A short calendar of public sessions</div>
        </div>
        <div class="muted">Capacity is limited — arrive early</div>
      </div>
      <ul class="calendar-list" aria-live="polite">
        <li><span>Sat, Mar 14 · 10:00 AM</span><span class="muted">Morning field</span></li>
        <li><span>Sun, Mar 22 · 4:00 PM</span><span class="muted">Soft evening</span></li>
        <li><span>Fri, Apr 3 · 7:00 PM</span><span class="muted">Weeknight pause</span></li>
        <li><span>Sat, Apr 18 · 11:30 AM</span><span class="muted">Weekend calm</span></li>
      </ul>
      <p class="disclaimer">Note: If you are pregnant, have a history of seizures, serious cardiac conditions, or are under medical treatment for psychiatric conditions, consult your healthcare provider before attending a session. Sound-based events are deeply relaxing and not a substitute for medical care.</p>
    </section>

    <section class="panel section reveal" id="gallery">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <div style="font-weight:700;color:#e6f9f6">A small gallery of the room</div>
        <div class="muted">Clean, warm, and intentionally arranged</div>
      </div>
      <div class="gallery" role="list">
        <div class="tile">Bowls &amp; space</div>
        <div class="tile">Soft light</div>
        <div class="tile">Seating layout</div>
      </div>
    </section>

    <section class="panel section reveal" id="faq">
      <h2 style="margin-top:0;color:#e6f9f6">Practical notes</h2>
      <div class="grid">
        <div class="card">
          <strong>What to bring</strong>
          <div class="muted">A mat or blanket, a small cushion, an open curiosity. Wear layers.</div>
        </div>
        <div class="card">
          <strong>Who attends</strong>
          <div class="muted">People seeking a focused break. Sessions are accessible to newcomers and regulars alike.</div>
        </div>
        <div class="card">
          <strong>Sound level</strong>
          <div class="muted">Intentionally varied: some sustained tones, gentle percussion. You control distance and comfort.</div>
        </div>
      </div>
      <p class="disclaimer">Accessibility: If you need accommodations please contact us at {{EMAIL}} or call {{PHONE}}.</p>
    </section>

    <section class="panel section reveal" id="cta">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <div>
          <div style="font-weight:700;color:#e6f9f6">Ready to join a gathering?</div>
          <div class="muted">Reserve a spot for the next session or get on the waitlist.</div>
        </div>
        <div>
          <a class="cta" href="book.html">Reserve a seat</a>
        </div>
      </div>
    </section>

  </main>
  <footer>
    &copy; <span id="year"></span> {{BUSINESS_NAME}} · <a href="contact.html" style="color:var(--muted);text-decoration:none">{{EMAIL}}</a> · <span class="muted">{{PHONE}}</span>
  </footer>
  <script>
    // year
    document.getElementById('year').textContent = new Date().getFullYear();

    // scroll reveal with reduced motion support
    (function(){
      var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var items = document.querySelectorAll('.reveal');
      if(prefersReduced){
        items.forEach(function(el){el.classList.add('visible')});
        return;
      }
      var io = new IntersectionObserver(function(entries){
        entries.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('visible'); io.unobserve(e.target); } });
      },{rootMargin:'-8% 0px',threshold:0.12});
      items.forEach(function(el){ io.observe(el); });
    })();
  </script>
</body>
</html>"} 
{"path":"private-sessions.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Solo Sessions — Private Sound Plans</title>
  <meta name="description" content="Private, tailored sound sessions in {{CITY}} — build a simple plan for a session and copy a plaintext summary to share or save.">
  <style>
    :root{--bg:#07121a;--card:#0b1a22;--muted:#9fb1b7;--accent:#7fe0d4;--glass:rgba(255,255,255,0.03);--radius:14px}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#08121a,#05131a),url('assets/img/pattern.svg');background-size:380px;color:#e8f6f4}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 26px}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#7fe0d4,#61a8ff);display:flex;align-items:center;justify-content:center;color:#022;font-weight:700}
    nav a{color:var(--muted);text-decoration:none;margin-left:16px}
    nav a.active{color:var(--accent);font-weight:700}
    main{max-width:1000px;margin:20px auto;padding:22px}
    .split{display:grid;grid-template-columns:1fr 420px;gap:20px}
    .panel{background:var(--card);padding:18px;border-radius:var(--radius);box-shadow:0 8px 30px rgba(2,6,23,0.6)}
    h1{margin:0 0 6px}
    .muted{color:var(--muted)}
    .widget label{display:block;margin-top:10px;font-weight:700}
    .widget input[type="text"],.widget textarea, .widget select{width:100%;padding:8px;margin-top:6px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:inherit}
    .controls{display:flex;gap:8px;margin-top:12px}
    .btn{background:var(--accent);color:#022;padding:10px 12px;border-radius:10px;text-decoration:none;border:none;font-weight:700;cursor:pointer}
    .summary{white-space:pre-wrap;background:rgba(255,255,255,0.02);padding:12px;border-radius:8px;margin-top:12px;border:1px solid rgba(255,255,255,0.03)}
    .disclaimer{font-size:13px;color:#b9d6d1;margin-top:10px}
    .reveal{opacity:0;transform:translateY(18px);transition:opacity 480ms cubic-bezier(.2,.9,.2,1),transform 480ms cubic-bezier(.2,.9,.2,1)}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html" class="active">Solo Sessions</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">Story</a>
      <a href="faq.html">Answers</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>
  <main>
    <section class="split">
      <div class="panel reveal">
        <div class="kicker muted">ONE-ON-ONE ARRANGEMENTS</div>
        <h1>Private sessions — made to fit</h1>
        <p class="muted">We design a session to match a practical aim: focused rest, recovery-focused listening, or a short reset. Use the planner to sketch a proposal and copy the plain summary to share with our team.</p>

        <div style="margin-top:16px">
          <h3 style="margin:0 0 8px;color:#eaf9f7">Session Planner</h3>
          <div class="widget" id="planner">
            <label for="client">Your name (optional)</label>
            <input id="client" type="text" placeholder="Full name">

            <label for="intention">Intention / goal</label>
            <input id="intention" type="text" placeholder="Restore focus, ease tension, sleep aid...">

            <label for="length">Duration</label>
            <select id="length">
              <option value="30">30 minutes</option>
              <option value="60" selected>60 minutes</option>
              <option value="90">90 minutes</option>
            </select>

            <label>Primary sounds</label>
            <div style="display:flex;gap:8px;margin-top:6px">
              <label style="font-weight:600"><input type="checkbox" value="Singing bowls" class="sound"> Singing bowls</label>
              <label style="font-weight:600"><input type="checkbox" value="Gong" class="sound"> Gong</label>
              <label style="font-weight:600"><input type="checkbox" value="Chimes" class="sound"> Chimes</label>
              <label style="font-weight:600"><input type="checkbox" value="Voice" class="sound"> Voice</label>
            </div>

            <label for="frequency">Suggested cadence</label>
            <select id="frequency">
              <option value="single">Single session</option>
              <option value="weekly">Weekly</option>
              <option value="monthly">Monthly</option>
            </select>

            <div class="controls">
              <button id="build" class="btn">Build plan</button>
              <button id="copy" class="btn" style="background:#4aa89f">Copy summary</button>
            </div>

            <div id="summary" class="summary" aria-live="polite">No plan yet — use "Build plan" to compose your summary.</div>
          </div>
        </div>

        <p class="disclaimer">Contraindications: If you have epilepsy, recent head injury, a pacemaker, are pregnant, or have an implanted device, please consult your physician before booking private sound work.</p>
      </div>

      <aside class="panel reveal">
        <h3 style="margin-top:0">How a private session runs</h3>
        <ol class="muted">
          <li>Short intake and position: 8–12 minutes.</li>
          <li>Attunement and extended sound field adapted to your aim.</li>
          <li>Slow re-entry and brief integration reflections.</li>
        </ol>

        <div style="margin-top:12px">
          <div style="font-weight:700;color:#eaf9f7">Practicalities</div>
          <div class="muted">In-person at our studio in {{CITY}} or remote via a guided audio session.</div>
          <div style="margin-top:10px"><a class="btn" href="{{PRIMARY_CTA_URL}}">Request a session</a></div>
        </div>
      </aside>
    </section>
  </main>
  <script>
    // reveal
    (function(){
      var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var items = document.querySelectorAll('.reveal');
      if(prefersReduced){ items.forEach(function(e){ e.classList.add('visible') }); return; }
      var io = new IntersectionObserver(function(entries){ entries.forEach(function(en){ if(en.isIntersecting){ en.target.classList.add('visible'); io.unobserve(en.target); } }); },{threshold:0.08});
      items.forEach(function(i){ io.observe(i); });
    })();

    // Session Planner logic
    (function(){
      var build = document.getElementById('build');
      var copyBtn = document.getElementById('copy');
      var summary = document.getElementById('summary');
      function gather(){
        var client = document.getElementById('client').value.trim();
        var intention = document.getElementById('intention').value.trim() || '[no stated intention]';
        var length = document.getElementById('length').value;
        var freq = document.getElementById('frequency').value;
        var sounds = Array.prototype.slice.call(document.querySelectorAll('.sound')).filter(function(cb){ return cb.checked; }).map(function(cb){ return cb.value; });
        if(sounds.length===0) sounds = ['Ambient bowls'];
        var when = (freq==='single')? 'single session' : (freq==='weekly')? 'weekly' : 'monthly';
        var who = client || 'Client not specified';
        var plan = [];
        plan.push('Personal session plan');
        plan.push('— Name: '+who);
        plan.push('— Intention: '+intention);
        plan.push('— Duration: '+length+' minutes');
        plan.push('— Cadence: '+when);
        plan.push('— Primary sounds: '+sounds.join(', '));
        plan.push('Notes: Private session will include short intake, tailored sound field, and a guided reintegration.');
        return plan.join('\n');
      }
      build.addEventListener('click',function(){ summary.textContent = gather(); });
      copyBtn.addEventListener('click',function(){
        var text = summary.textContent;
        if(!text || text.indexOf('No plan yet')===0) { alert('Build the plan first.'); return; }
        navigator.clipboard && navigator.clipboard.writeText(text).then(function(){
          copyBtn.textContent = 'Copied'; setTimeout(function(){ copyBtn.textContent = 'Copy summary'; },1500);
        },function(){ alert('Copy failed — select the text and copy.'); });
      });
    })();
  </script>
</body>
</html>"} 
{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Pricing &amp; Tiers</title>
  <meta name="description" content="Investment tiers for private and public sound sessions. Transparent guidance and a small planner to estimate the right offering for you.">
  <style>
    :root{--bg:#07131a;--card:#071b22;--muted:#9cc3be;--accent:#9cf2df;--radius:12px}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#041018,#071a20),url('assets/img/pattern.svg');background-size:360px;color:#e7f8f6}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 24px}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#9cf2df,#61a8ff);display:flex;align-items:center;justify-content:center;color:#022;font-weight:700}
    nav a{color:var(--muted);margin-left:14px;text-decoration:none}
    nav a.active{color:var(--accent);font-weight:700}
    main{max-width:980px;margin:18px auto;padding:22px}
    .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
    .card{background:var(--card);padding:16px;border-radius:12px;border:1px solid rgba(255,255,255,0.02)}
    h1{margin:0 0 8px}
    .price{font-weight:800;color:var(--accent);font-size:20px}
    .muted{color:var(--muted)}
    .note{font-size:13px;color:#bfeee6}
    .reveal{opacity:0;transform:translateY(16px);transition:opacity 520ms cubic-bezier(.2,.9,.2,1),transform 520ms cubic-bezier(.2,.9,.2,1)}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
    .planner{margin-top:18px;background:rgba(255,255,255,0.02);padding:12px;border-radius:10px}
    .planner input,.planner select{width:100%;padding:8px;margin-top:8px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);background:transparent;color:inherit}
    .btn{background:var(--accent);color:#022;padding:8px 12px;border-radius:10px;border:none;font-weight:700;cursor:pointer}
    .summary{margin-top:10px;background:rgba(255,255,255,0.02);padding:10px;border-radius:8px}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Solo Sessions</a>
      <a href="pricing.html" class="active">Invest</a>
      <a href="about.html">Story</a>
      <a href="faq.html">Answers</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>
  <main>
    <section class="reveal">
      <h1>Investment tiers</h1>
      <p class="muted">Simple, named tiers to help you pick a rhythm that makes sense. We keep pricing transparent and suggest options depending on session type and duration.</p>
    </section>

    <section class="grid reveal" style="margin-top:18px">
      <div class="card">
        <div class="note">Solo — intro</div>
        <h2 style="margin:8px 0">Quiet Session</h2>
        <div class="price">$95 — 30 min</div>
        <p class="muted">A focused 30-minute private arrangement. A good first step.</p>
      </div>
      <div class="card">
        <div class="note">Standard</div>
        <h2 style="margin:8px 0">Deep Pause</h2>
        <div class="price">$175 — 60 min</div>
        <p class="muted">Most requested: a full 60 minute private session with a short intake.</p>
      </div>
      <div class="card">
        <div class="note">Curated bundle</div>
        <h2 style="margin:8px 0">Reset Series</h2>
        <div class="price">$480 — 3×60 min</div>
        <p class="muted">Three sessions planned to build a small pattern of renewal. Best value per session.</p>
      </div>
    </section>

    <section class="reveal" style="margin-top:20px">
      <h2 style="margin:0">Planner &amp; Estimate</h2>
      <p class="muted">Choose duration and cadence to get a suggested investment and a plaintext summary you can copy.</p>
      <div class="planner">
        <label style="font-weight:700">Duration</label>
        <select id="p-duration"><option value="30">30</option><option value="60" selected>60</option><option value="90">90</option></select>
        <label style="font-weight:700;margin-top:8px">Cadence</label>
        <select id="p-cadence"><option value="single">Single</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select>
        <label style="font-weight:700;margin-top:8px">Notes (optional)</label>
        <input id="p-notes" placeholder="Short note about intention">
        <div style="display:flex;gap:8px;margin-top:10px">
          <button id="p-build" class="btn">Estimate</button>
          <button id="p-copy" class="btn" style="background:#4aa89f">Copy</button>
        </div>
        <div id="p-summary" class="summary">No estimate yet.</div>
      </div>
    </section>

    <section class="reveal" style="margin-top:16px">
      <p class="muted">If you have medical concerns (pregnancy, epilepsy, implanted medical devices), consult your healthcare provider before engaging in sound sessions. For questions about accessibility or specific needs reach out at {{EMAIL}} or call {{PHONE}}.</p>
      <div style="margin-top:12px"><a class="btn" href="book.html">Reserve a time</a></div>
    </section>

  </main>
  <script>
    // reveal
    (function(){
      var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var items = document.querySelectorAll('.reveal');
      if(prefersReduced){ items.forEach(function(e){ e.classList.add('visible') }); return; }
      var io = new IntersectionObserver(function(entries){ entries.forEach(function(en){ if(en.isIntersecting){ en.target.classList.add('visible'); io.unobserve(en.target); } }); },{threshold:0.08});
      items.forEach(function(i){ io.observe(i); });
    })();

    // pricing planner
    (function(){
      var elDur = document.getElementById('p-duration');
      var elCad = document.getElementById('p-cadence');
      var elNotes = document.getElementById('p-notes');
      var elBuild = document.getElementById('p-build');
      var elCopy = document.getElementById('p-copy');
      var elSummary = document.getElementById('p-summary');

      function estimate(){
        var dur = parseInt(elDur.value,10);
        var cadence = elCad.value;
        var notes = elNotes.value.trim() || '[no notes]';
        var base = (dur===30)?95:(dur===60)?175:255;
        var multiplier = (cadence==='single')?1:(cadence==='weekly')?0.88:0.92;
        var suggested = Math.round(base * multiplier);
        var lines = [];
        lines.push('Session estimate');
        lines.push('— Duration: '+dur+' minutes');
        lines.push('— Cadence: '+cadence);
        lines.push('— Suggested investment (per session): $'+suggested);
        lines.push('— Notes: '+notes);
        if(cadence!=='single') lines.push('— Package pricing may be available — ask on booking.');
        return lines.join('\n');
      }

      elBuild.addEventListener('click',function(){ elSummary.textContent = estimate(); });
      elCopy.addEventListener('click',function(){
        var text = elSummary.textContent;
        if(!text || text.indexOf('No estimate')===0){ alert('Create an estimate first.'); return; }
        navigator.clipboard && navigator.clipboard.writeText(text).then(function(){ elCopy.textContent = 'Copied'; setTimeout(function(){ elCopy.textContent = 'Copy'; },1400); },function(){ alert('Copy failed.'); });
      });
    })();
  </script>
